def calc_w_stars(n, m):
    if n % m != 0: return 0
    k = n // m
    return k * (m-1) * ((n-m)*(n-m-1)//2 - (k-1)*(m-1))

n = 120
max_w_stars = 0
for m in range(2, n + 1):
    if n % m == 0:
        max_w_stars = max(max_w_stars, calc_w_stars(n, m))
print(f"Max W stars: {max_w_stars}")
